  http {
      resolver 10.0.0.2 valid=30s ipv4=on ipv6=off;
      resolver_timeout 5s;

      upstream dynamic_backend {
          zone dynamic_backend 64k;
          server backend.internal.example.com resolve;
      }

      server {
          location / {
              proxy_pass http://dynamic_backend;
          }
      }
  }
  ```

  ```bash
  nginx -t && nginx -s reload
  ```

